#!/usr/bin/env python3
from pathlib import Path
import html
import re

ROOT = Path(__file__).resolve().parents[1]
LIBRARY = ROOT / "library.html"

RATIONALES = {'obesity': ('Ketogenic strategies are studied in obesity because carbohydrate restriction and nutritional ketosis can influence appetite, insulin signaling, substrate oxidation and spontaneous energy intake; in VLCKD/VLEKT, the large energy deficit is also a major driver of weight loss.', 'Le strategie chetogeniche vengono studiate nell’obesità perché restrizione dei carboidrati e chetosi nutrizionale possono influenzare appetito, segnalazione insulinica, ossidazione dei substrati e introito energetico spontaneo; nelle VLCKD/VLEKT anche l’ampio deficit energetico è un determinante importante del calo ponderale.'), 'glp1-keto-metabolic-endocrine': ('Combining ketogenic interventions with GLP-1–based therapies is being studied because both can modify appetite, glycemic control and energy balance, while nutritional composition may also influence body composition and lean-tissue preservation during pharmacological weight loss.', 'L’associazione tra interventi chetogenici e terapie basate su GLP-1 viene studiata perché entrambi possono modificare appetito, controllo glicemico e bilancio energetico, mentre la composizione nutrizionale può influenzare anche la composizione corporea e la preservazione della massa magra durante il dimagrimento farmacologico.'), 'diabetes-glucose-metabolism': ('Carbohydrate restriction can reduce postprandial glucose exposure and insulin requirements and may improve hepatic and peripheral insulin sensitivity; the magnitude and safety of these effects depend on diabetes type, medication and clinical context.', 'La restrizione dei carboidrati può ridurre l’esposizione glicemica post-prandiale e il fabbisogno insulinico e può migliorare la sensibilità insulinica epatica e periferica; entità e sicurezza di questi effetti dipendono dal tipo di diabete, dalla terapia farmacologica e dal contesto clinico.'), 'masld-metabolic-liver-disease': ('Ketogenic and very-low-energy ketogenic interventions are studied in MASLD because weight loss, lower insulin exposure and reduced de novo lipogenesis can decrease hepatic triglyceride accumulation; direct effects of ketone metabolism on liver biology remain under investigation.', 'Gli interventi chetogenici e chetogenici a bassissimo apporto energetico vengono studiati nella MASLD perché perdita di peso, riduzione dell’esposizione insulinica e minore lipogenesi de novo possono ridurre l’accumulo di trigliceridi epatici; gli effetti diretti del metabolismo chetonico sulla biologia epatica sono ancora oggetto di studio.'), 'dyslipidemia-lipid-metabolism': ('Ketogenic diets can markedly alter lipid trafficking, often lowering triglycerides and increasing HDL cholesterol, while LDL cholesterol and ApoB responses are heterogeneous and depend on diet composition, adiposity and individual phenotype.', 'Le diete chetogeniche possono modificare in modo rilevante il traffico lipidico, spesso riducendo i trigliceridi e aumentando il colesterolo HDL, mentre le risposte di colesterolo LDL e ApoB sono eterogenee e dipendono dalla composizione della dieta, dall’adiposità e dal fenotipo individuale.'), 'lipid-energy-model-lmhr': ('The LMHR phenotype is studied as an extreme lipid response to carbohydrate restriction in some lean individuals. Proposed mechanisms involve increased fatty-acid flux and lipoprotein trafficking during high reliance on fat oxidation, but the Lipid Energy Model remains a hypothesis under active investigation.', 'Il fenotipo LMHR viene studiato come risposta lipidica estrema alla restrizione dei carboidrati in alcuni individui magri. I meccanismi proposti coinvolgono un aumento del flusso di acidi grassi e del traffico lipoproteico durante un’elevata dipendenza dall’ossidazione lipidica, ma il Lipid Energy Model resta un’ipotesi in corso di verifica.'), 'thyroid-disorders': ('Ketosis and energy restriction can modify thyroid-hormone metabolism, particularly circulating T3 and peripheral deiodination. Whether these adaptations represent physiological energy conservation or clinically relevant thyroid dysfunction depends on the clinical setting.', 'Chetosi e restrizione energetica possono modificare il metabolismo degli ormoni tiroidei, in particolare il T3 circolante e la deiodinazione periferica. Il significato di tali adattamenti — conservazione energetica fisiologica o disfunzione clinicamente rilevante — dipende dal contesto.'), 'cushing-syndrome': ('Interest in ketogenic approaches in Cushing syndrome is mainly linked to the metabolic consequences of cortisol excess—insulin resistance, visceral adiposity and dysglycemia—rather than to an established direct effect on the underlying hypercortisolism.', 'L’interesse per gli approcci chetogenici nella sindrome di Cushing riguarda soprattutto le conseguenze metaboliche dell’eccesso di cortisolo — insulino-resistenza, adiposità viscerale e disglicemia — più che un effetto diretto dimostrato sull’ipercortisolismo sottostante.'), 'polyendocrine-metabolic-ovarian-syndrome-pmos-formerly-pcos': ('Ketogenic interventions are studied in PMOS/PCOS because lowering hyperinsulinemia and improving insulin sensitivity may reduce insulin-driven ovarian androgen production, while weight loss can further influence reproductive and metabolic outcomes.', 'Gli interventi chetogenici vengono studiati nella PMOS/PCOS perché la riduzione dell’iperinsulinemia e il miglioramento della sensibilità insulinica possono attenuare la produzione ovarica di androgeni mediata dall’insulina, mentre il dimagrimento può influenzare ulteriormente gli esiti riproduttivi e metabolici.'), 'epilepsy': ('Ketogenic therapy can reduce neuronal excitability through multiple interacting pathways involving ketone metabolism, mitochondrial energetics, GABA/glutamate balance, adenosine signaling and ion-channel regulation. This is the best-established therapeutic application of ketogenic diets.', 'La terapia chetogenica può ridurre l’eccitabilità neuronale attraverso più vie interagenti che coinvolgono metabolismo dei chetoni, bioenergetica mitocondriale, equilibrio GABA/glutammato, segnalazione dell’adenosina e regolazione dei canali ionici. È l’applicazione terapeutica più consolidata delle diete chetogeniche.'), 'alzheimers-disease': ('Alzheimer’s disease is associated with early impairment of cerebral glucose utilization, while ketone uptake can remain relatively preserved. Ketogenic interventions are therefore studied as an alternative brain fuel and for possible effects on mitochondrial function, oxidative stress, neuroinflammation and neuronal signaling.', 'La malattia di Alzheimer è associata a una compromissione precoce dell’utilizzazione cerebrale del glucosio, mentre l’uptake dei chetoni può rimanere relativamente preservato. Gli interventi chetogenici vengono quindi studiati come fonte energetica cerebrale alternativa e per possibili effetti su funzione mitocondriale, stress ossidativo, neuroinfiammazione e segnalazione neuronale.'), 'parkinsons-disease': ('Ketogenic strategies are investigated in Parkinson’s disease because mitochondrial dysfunction, oxidative stress and impaired neuronal energy metabolism are central biological targets; modulation of neuroinflammation and dopaminergic resilience is also proposed, with much of the mechanistic evidence still preclinical.', 'Le strategie chetogeniche vengono studiate nella malattia di Parkinson perché disfunzione mitocondriale, stress ossidativo e alterato metabolismo energetico neuronale rappresentano bersagli biologici centrali; sono inoltre proposti effetti su neuroinfiammazione e resilienza dopaminergica, con gran parte dell’evidenza meccanicistica ancora preclinica.'), 'huntingtons-disease': ('Huntington’s disease involves profound abnormalities of neuronal energy metabolism and mitochondrial function. Ketone bodies are being studied as alternative oxidative substrates and metabolic signals, but direct clinical evidence remains limited.', 'La malattia di Huntington comporta profonde alterazioni del metabolismo energetico neuronale e della funzione mitocondriale. I corpi chetonici vengono studiati come substrati ossidativi alternativi e segnali metabolici, ma l’evidenza clinica diretta resta limitata.'), 'neurodegenerative-disorders': ('Across neurodegenerative disorders, ketogenic interventions are investigated for their potential to support cerebral bioenergetics and modulate mitochondrial function, redox balance and neuroinflammatory signaling. The relevance of each pathway varies substantially by disease.', 'Nelle malattie neurodegenerative gli interventi chetogenici vengono studiati per il potenziale sostegno alla bioenergetica cerebrale e per la modulazione di funzione mitocondriale, equilibrio redox e segnalazione neuroinfiammatoria. La rilevanza delle singole vie varia notevolmente tra le diverse patologie.'), 'glut1-deficiency-syndrome': ('In GLUT1 deficiency, impaired glucose transport across the blood–brain barrier limits cerebral fuel availability. Ketone bodies bypass this transport defect and provide the brain with an alternative energy substrate, forming the core rationale for ketogenic therapy.', 'Nel deficit di GLUT1, l’alterato trasporto del glucosio attraverso la barriera emato-encefalica limita la disponibilità energetica cerebrale. I corpi chetonici bypassano questo difetto di trasporto e forniscono al cervello un substrato energetico alternativo, costituendo il razionale centrale della terapia chetogenica.'), 'pyruvate-dehydrogenase-deficiency': ('Pyruvate dehydrogenase deficiency limits conversion of glucose-derived pyruvate into acetyl-CoA. Ketone bodies provide acetyl-CoA through an alternative pathway, reducing dependence on the blocked enzymatic step and supporting cerebral energy metabolism.', 'Il deficit di piruvato deidrogenasi limita la conversione del piruvato derivato dal glucosio in acetil-CoA. I corpi chetonici forniscono acetil-CoA attraverso una via alternativa, riducendo la dipendenza dal passaggio enzimatico bloccato e sostenendo il metabolismo energetico cerebrale.'), 'brain-injury-neurotrauma': ('After brain injury, glucose metabolism may become impaired while energetic demand remains high. Ketones are studied as alternative cerebral fuel and for potential effects on mitochondrial function, excitotoxicity, oxidative stress and neuroinflammation; timing and injury type are likely important.', 'Dopo un danno cerebrale il metabolismo del glucosio può risultare compromesso mentre la richiesta energetica resta elevata. I chetoni vengono studiati come combustibile cerebrale alternativo e per possibili effetti su funzione mitocondriale, eccitotossicità, stress ossidativo e neuroinfiammazione; timing e tipo di lesione sono probabilmente determinanti.'), 'cognitive-function': ('Ketogenic interventions may influence cognition by changing cerebral fuel availability and metabolic signaling. Effects can differ according to age, baseline metabolic status, cognitive impairment and whether ketosis is achieved through diet, MCTs or exogenous ketones.', 'Gli interventi chetogenici possono influenzare la funzione cognitiva modificando la disponibilità di substrati energetici cerebrali e la segnalazione metabolica. Gli effetti possono differire in base a età, stato metabolico di partenza, compromissione cognitiva e modalità con cui viene ottenuta la chetosi — dieta, MCT o chetoni esogeni.'), 'headache-migraine': ('Ketogenic therapy is studied in migraine because neuronal hyperexcitability, cortical spreading depolarization, mitochondrial energetics and oxidative stress are plausible metabolic targets. More stable glucose availability and ketone signaling may also contribute.', 'La terapia chetogenica viene studiata nell’emicrania perché ipereccitabilità neuronale, depolarizzazione corticale propagata, bioenergetica mitocondriale e stress ossidativo rappresentano plausibili bersagli metabolici. Possono contribuire anche una maggiore stabilità della disponibilità energetica e la segnalazione dei chetoni.'), 'multiple-sclerosis': ('In multiple sclerosis, ketogenic interventions are investigated for possible effects on immune-cell metabolism, mitochondrial function, oxidative stress and neuroinflammatory signaling. Clinical evidence is developing but remains less established than in epilepsy.', 'Nella sclerosi multipla gli interventi chetogenici vengono studiati per possibili effetti sul metabolismo delle cellule immunitarie, sulla funzione mitocondriale, sullo stress ossidativo e sulla segnalazione neuroinfiammatoria. L’evidenza clinica è in sviluppo ma resta meno consolidata rispetto all’epilessia.'), 'autism-spectrum-disorder': ('Ketogenic approaches in autism are investigated through several proposed pathways, including mitochondrial metabolism, neuronal excitation–inhibition balance, neuroinflammation and gut–brain signaling. Autism is highly heterogeneous and the clinical relevance of these mechanisms remains uncertain.', 'Gli approcci chetogenici nell’autismo vengono studiati attraverso diverse vie proposte, tra cui metabolismo mitocondriale, equilibrio eccitazione–inibizione neuronale, neuroinfiammazione e asse intestino–cervello. L’autismo è altamente eterogeneo e la rilevanza clinica di questi meccanismi resta incerta.'), 'psychiatry-mental-health': ('Ketogenic metabolic therapy is being explored in psychiatry because mitochondrial function, insulin signaling, cellular energetics and GABA/glutamate balance may be altered in subsets of psychiatric disorders. Clinical evidence is still emerging and varies markedly by diagnosis.', 'La terapia metabolica chetogenica viene esplorata in psichiatria perché funzione mitocondriale, segnalazione insulinica, bioenergetica cellulare ed equilibrio GABA/glutammato possono risultare alterati in sottogruppi di disturbi psichiatrici. L’evidenza clinica è ancora emergente e varia molto tra le diagnosi.'), 'substance-use-disorders': ('Ketogenic interventions are being studied in substance-use disorders for possible effects on brain energy metabolism, reward circuitry, glutamate/GABA signaling and withdrawal-related metabolic stress. Human evidence remains early.', 'Gli interventi chetogenici vengono studiati nei disturbi da uso di sostanze per possibili effetti sul metabolismo energetico cerebrale, sui circuiti della ricompensa, sulla segnalazione glutammato/GABA e sullo stress metabolico associato all’astinenza. L’evidenza nell’uomo è ancora iniziale.'), 'eating-disorders': ('The relationship between ketosis and eating disorders is complex. Research may address appetite regulation, reward signaling and metabolic adaptation, but ketogenic diets are not an established treatment for eating disorders and restrictive interventions require particular clinical caution.', 'Il rapporto tra chetosi e disturbi dell’alimentazione è complesso. La ricerca può riguardare regolazione dell’appetito, circuiti della ricompensa e adattamento metabolico, ma le diete chetogeniche non rappresentano un trattamento consolidato dei disturbi alimentari e gli interventi restrittivi richiedono particolare cautela clinica.'), 'oncology-cancer-metabolism': ('Ketogenic strategies in oncology are investigated because some tumors show high glucose dependence and altered metabolic flexibility. Proposed mechanisms include lower insulin/IGF signaling, metabolic stress, redox modulation and immune effects, but tumor biology is heterogeneous and clinical efficacy is not established across cancers.', 'Le strategie chetogeniche in oncologia vengono studiate perché alcuni tumori mostrano elevata dipendenza dal glucosio e alterata flessibilità metabolica. I meccanismi proposti comprendono riduzione della segnalazione insulina/IGF, stress metabolico, modulazione redox ed effetti immunitari, ma la biologia tumorale è eterogenea e l’efficacia clinica non è dimostrata in modo generalizzabile.'), 'cardiovascular-health': ('Potential cardiovascular effects of ketogenic diets arise from changes in body weight, blood pressure, glycemic control, triglyceride-rich lipoproteins and inflammation. LDL cholesterol and ApoB responses can vary widely, making diet composition and individual phenotype important.', 'I potenziali effetti cardiovascolari delle diete chetogeniche derivano da modificazioni di peso corporeo, pressione arteriosa, controllo glicemico, lipoproteine ricche in trigliceridi e infiammazione. Le risposte di colesterolo LDL e ApoB possono variare ampiamente, rendendo importanti composizione della dieta e fenotipo individuale.'), 'adpkd': ('Ketogenic interventions are being studied in ADPKD because cystic cells show altered energy metabolism and because ketone signaling may influence pathways involved in cyst growth, inflammation and mitochondrial function. Much of the mechanistic support remains preclinical.', 'Gli interventi chetogenici vengono studiati nell’ADPKD perché le cellule cistiche presentano un metabolismo energetico alterato e perché la segnalazione dei chetoni può influenzare vie coinvolte nella crescita cistica, nell’infiammazione e nella funzione mitocondriale. Gran parte del supporto meccanicistico resta preclinico.'), 'chronic-kidney-disease': ('Ketone metabolism is increasingly studied in kidney disease because ketone bodies can act as oxidative substrates and signaling molecules affecting mitochondrial function, inflammation and oxidative stress. Clinical relevance and safety depend strongly on kidney function, comorbidities and treatment context.', 'Il metabolismo dei chetoni viene sempre più studiato nella malattia renale perché i corpi chetonici possono agire come substrati ossidativi e molecole di segnalazione influenzando funzione mitocondriale, infiammazione e stress ossidativo. Rilevanza clinica e sicurezza dipendono fortemente dalla funzione renale, dalle comorbidità e dal contesto terapeutico.'), 'urinary-incontinence': ('The most plausible link between ketogenic weight-loss interventions and urinary incontinence is indirect: reduction of excess body weight can decrease abdominal and pelvic-floor mechanical load. A specific ketone-mediated mechanism has not been established.', 'Il collegamento più plausibile tra interventi chetogenici per il dimagrimento e incontinenza urinaria è indiretto: la riduzione dell’eccesso ponderale può diminuire il carico meccanico addominale e sul pavimento pelvico. Non è stato dimostrato uno specifico meccanismo mediato dai chetoni.'), 'sarcopenia-skeletal-muscle': ('Ketosis and β-hydroxybutyrate are studied for possible effects on muscle energetics, mitochondrial function and catabolic signaling. In clinical practice, however, preservation of skeletal muscle during weight loss also depends critically on adequate protein intake, resistance exercise and the magnitude of energy restriction.', 'Chetosi e β-idrossibutirrato vengono studiati per possibili effetti su bioenergetica muscolare, funzione mitocondriale e segnalazione catabolica. Nella pratica clinica, tuttavia, la preservazione del muscolo durante il dimagrimento dipende in modo determinante anche da adeguato apporto proteico, esercizio di resistenza ed entità della restrizione energetica.'), 'osteoarthritis': ('In osteoarthritis, the strongest rationale for ketogenic weight-loss strategies is reduction of mechanical joint loading through loss of excess body weight. Possible effects on metabolic inflammation are also studied, whereas direct ketone-specific effects on joint disease remain uncertain.', 'Nell’osteoartrosi il razionale più solido degli interventi chetogenici finalizzati al dimagrimento è la riduzione del carico meccanico articolare conseguente alla perdita dell’eccesso ponderale. Vengono studiati anche possibili effetti sull’infiammazione metabolica, mentre gli effetti diretti specifici dei chetoni sulla malattia articolare restano incerti.'), 'rheumatoid-arthritis': ('Ketogenic interventions in rheumatoid arthritis are mainly investigated through immunometabolic pathways, including changes in inflammatory signaling and β-hydroxybutyrate–related modulation of the NLRP3 inflammasome. Direct clinical evidence remains limited.', 'Gli interventi chetogenici nell’artrite reumatoide vengono studiati soprattutto attraverso vie immunometaboliche, incluse modificazioni della segnalazione infiammatoria e la modulazione dell’inflammasoma NLRP3 associata al β-idrossibutirrato. L’evidenza clinica diretta resta limitata.'), 'fibromyalgia': ('Ketogenic approaches in fibromyalgia are explored because altered energy metabolism, mitochondrial function, neuroinflammation and pain processing have been proposed as relevant biological targets. Clinical evidence is preliminary.', 'Gli approcci chetogenici nella fibromialgia vengono esplorati perché alterazioni del metabolismo energetico, della funzione mitocondriale, della neuroinfiammazione e dell’elaborazione del dolore sono state proposte come bersagli biologici rilevanti. L’evidenza clinica è preliminare.'), 'acne': ('Carbohydrate restriction may influence acne-related pathways through lower glycemic and insulin exposure, reduced IGF-1 signaling and downstream mTORC1 activity. Direct evidence for ketogenic diets as an acne treatment is still limited.', 'La restrizione dei carboidrati può influenzare vie coinvolte nell’acne attraverso minore esposizione glicemica e insulinica, riduzione della segnalazione IGF-1 e conseguente attività mTORC1. L’evidenza diretta sulle diete chetogeniche come trattamento dell’acne resta limitata.'), 'psoriasis': ('Interest in ketogenic interventions in psoriasis is linked mainly to weight reduction, insulin sensitivity and systemic inflammatory signaling. Direct effects of nutritional ketosis on psoriatic immune pathways are plausible but not yet clinically established.', 'L’interesse per gli interventi chetogenici nella psoriasi riguarda soprattutto riduzione del peso, sensibilità insulinica e segnalazione infiammatoria sistemica. Effetti diretti della chetosi nutrizionale sulle vie immunitarie psoriasiche sono plausibili ma non ancora clinicamente consolidati.'), 'keto-rash-prurigo-pigmentosa': ('Prurigo pigmentosa is relevant to ketogenic therapy primarily as a potential adverse cutaneous association with ketosis rather than as a therapeutic indication. Proposed mechanisms include ketosis-related inflammatory changes, but the pathogenesis remains incompletely understood.', 'La prurigo pigmentosa è rilevante per la terapia chetogenica soprattutto come possibile associazione cutanea avversa alla chetosi, non come indicazione terapeutica. I meccanismi proposti includono modificazioni infiammatorie associate alla chetosi, ma la patogenesi resta incompletamente definita.'), 'asthma': ('Ketogenic interventions in asthma are being explored through obesity-related metabolic pathways and possible modulation of airway inflammation and immune-cell metabolism. Most ketone-specific mechanistic evidence is preclinical.', 'Gli interventi chetogenici nell’asma vengono esplorati attraverso vie metaboliche legate all’obesità e una possibile modulazione dell’infiammazione delle vie aeree e del metabolismo delle cellule immunitarie. Gran parte dell’evidenza meccanicistica specifica sui chetoni è preclinica.'), 'inflammation-immunometabolism': ('β-Hydroxybutyrate is not only an energy substrate but also a signaling metabolite. It can influence immune-cell metabolism, histone deacetylase activity and inflammatory pathways including NLRP3, providing a mechanistic link between ketosis and immunometabolism.', 'Il β-idrossibutirrato non è soltanto un substrato energetico ma anche un metabolita di segnalazione. Può influenzare il metabolismo delle cellule immunitarie, l’attività delle istone deacetilasi e vie infiammatorie tra cui NLRP3, fornendo un collegamento meccanicistico tra chetosi e immunometabolismo.'), 'endometriosis': ('Ketogenic strategies in endometriosis are being explored through potential effects on insulin signaling, inflammatory tone, oxidative stress and body composition. Disease-specific clinical and mechanistic evidence remains limited.', 'Le strategie chetogeniche nell’endometriosi vengono esplorate per possibili effetti su segnalazione insulinica, tono infiammatorio, stress ossidativo e composizione corporea. Le evidenze cliniche e meccanicistiche specifiche per la malattia restano limitate.'), 'reproduction-fertility': ('Ketogenic interventions may affect reproductive physiology indirectly through body weight, insulin sensitivity and endocrine signaling. Potential effects vary substantially by sex, underlying diagnosis and energy availability, so no single fertility mechanism applies across populations.', 'Gli interventi chetogenici possono influenzare indirettamente la fisiologia riproduttiva attraverso peso corporeo, sensibilità insulinica e segnalazione endocrina. I possibili effetti variano notevolmente in base a sesso, diagnosi di base e disponibilità energetica, quindi non esiste un unico meccanismo applicabile a tutte le popolazioni.'), 'lipedema': ('Ketogenic approaches in lipedema are studied for possible effects on pain, edema, adipose-tissue metabolism, inflammation and body composition. Evidence is emerging and it remains unclear which effects are specific to ketosis rather than weight or dietary change.', 'Gli approcci chetogenici nel lipedema vengono studiati per possibili effetti su dolore, edema, metabolismo del tessuto adiposo, infiammazione e composizione corporea. L’evidenza è emergente e non è ancora chiaro quali effetti siano specifici della chetosi rispetto al dimagrimento o al cambiamento alimentare.'), 'longevity-healthy-aging': ('Ketosis intersects with pathways involved in cellular stress responses and nutrient sensing, including AMPK, mTOR, sirtuins, autophagy and β-hydroxybutyrate signaling. These mechanisms are biologically plausible, but extension of human lifespan by ketogenic diets has not been demonstrated.', 'La chetosi interagisce con vie coinvolte nelle risposte cellulari allo stress e nel nutrient sensing, tra cui AMPK, mTOR, sirtuine, autofagia e segnalazione del β-idrossibutirrato. Questi meccanismi sono biologicamente plausibili, ma un’estensione della durata della vita umana mediante dieta chetogenica non è stata dimostrata.'), 'circadian-rhythms': ('Ketone production and utilization vary with feeding–fasting cycles, and ketogenic diets can alter metabolic signals that interact with peripheral circadian clocks. The physiological and clinical consequences of these interactions in humans remain under study.', 'Produzione e utilizzo dei chetoni variano con i cicli alimentazione–digiuno e le diete chetogeniche possono modificare segnali metabolici che interagiscono con gli orologi circadiani periferici. Le conseguenze fisiologiche e cliniche di queste interazioni nell’uomo sono ancora oggetto di studio.'), 'gut-microbiome': ('Ketogenic diets can reshape the gut microbiome by markedly changing carbohydrate, fiber and fat exposure, with downstream effects on microbial metabolites and host immunity. Responses are highly dependent on the specific formulation of the diet.', 'Le diete chetogeniche possono rimodellare il microbiota intestinale modificando in modo marcato l’esposizione a carboidrati, fibre e grassi, con effetti a valle sui metaboliti microbici e sull’immunità dell’ospite. Le risposte dipendono fortemente dalla specifica formulazione della dieta.'), 'candida-mycobiome': ('Carbohydrate availability and broader dietary composition can influence fungal ecology and host–microbe interactions, providing a rationale for studying ketogenic diets and the mycobiome. Clinical evidence that ketosis directly treats Candida-related disease is currently insufficient.', 'La disponibilità di carboidrati e la composizione complessiva della dieta possono influenzare l’ecologia fungina e le interazioni ospite–microbiota, fornendo un razionale per studiare dieta chetogenica e micobioma. Le evidenze cliniche che la chetosi tratti direttamente patologie correlate a Candida sono attualmente insufficienti.'), 'exogenous-ketones': ('Exogenous ketones raise circulating ketone concentrations without requiring the same degree of carbohydrate restriction or hepatic ketogenesis. They are used to isolate fuel and signaling effects of ketones from the broader physiological effects of a ketogenic diet.', 'I chetoni esogeni aumentano le concentrazioni circolanti di corpi chetonici senza richiedere lo stesso grado di restrizione dei carboidrati o di chetogenesi epatica. Vengono utilizzati per distinguere gli effetti energetici e di segnalazione dei chetoni dagli effetti fisiologici più ampi di una dieta chetogenica.'), 'medium-chain-triglycerides-mct': ('Medium-chain triglycerides are rapidly absorbed and preferentially oxidized in the liver, where they can increase ketone production more efficiently than long-chain fats. This allows higher ketone availability with less stringent carbohydrate restriction in some therapeutic protocols.', 'I trigliceridi a catena media vengono assorbiti rapidamente e ossidati preferenzialmente nel fegato, dove possono aumentare la produzione di chetoni più efficientemente dei grassi a catena lunga. Ciò consente in alcuni protocolli terapeutici una maggiore disponibilità di chetoni con una restrizione dei carboidrati meno severa.'), 'supplementation-nutraceuticals': ('This area includes heterogeneous adjuncts rather than a single mechanism. Electrolytes, micronutrients, amino acids, fatty acids and other compounds may be used to correct deficiencies, support tolerability or target specific metabolic pathways during ketogenic therapy; effects are ingredient-specific.', 'Quest’area comprende coadiuvanti eterogenei e non un singolo meccanismo. Elettroliti, micronutrienti, aminoacidi, acidi grassi e altri composti possono essere utilizzati per correggere carenze, migliorare la tollerabilità o modulare specifiche vie metaboliche durante la terapia chetogenica; gli effetti dipendono dal singolo ingrediente.'), 'exercise-performance': ('Ketogenic adaptation shifts substrate use toward fat oxidation and can modify glycogen utilization, ketone oxidation and mitochondrial metabolism during exercise. Performance effects depend strongly on exercise intensity, duration, sport type and adaptation period.', 'L’adattamento chetogenico sposta l’utilizzo dei substrati verso una maggiore ossidazione dei grassi e può modificare uso del glicogeno, ossidazione dei chetoni e metabolismo mitocondriale durante l’esercizio. Gli effetti sulla performance dipendono fortemente da intensità, durata, tipo di sport e periodo di adattamento.'), 'glaucoma': ('Ketogenic strategies are being investigated in glaucoma because retinal ganglion cells are vulnerable to mitochondrial dysfunction, oxidative stress and impaired energy metabolism. Ketones may provide alternative fuel and signaling effects, but evidence is predominantly preclinical.', 'Le strategie chetogeniche vengono studiate nel glaucoma perché le cellule ganglionari retiniche sono vulnerabili a disfunzione mitocondriale, stress ossidativo e alterazioni del metabolismo energetico. I chetoni possono fornire un substrato alternativo e segnali metabolici, ma l’evidenza è prevalentemente preclinica.'), 'down-syndrome': ('Down syndrome is associated with characteristic metabolic, mitochondrial and oxidative-stress abnormalities. Ketogenic interventions are being explored as metabolic modulators, but disease-specific evidence remains very limited and largely experimental.', 'La sindrome di Down è associata a caratteristiche alterazioni metaboliche, mitocondriali e dello stress ossidativo. Gli interventi chetogenici vengono esplorati come modulatori metabolici, ma le evidenze specifiche per la condizione restano molto limitate e in gran parte sperimentali.'), 'gilbert-syndrome': ('In Gilbert syndrome, fasting and energy restriction can increase unconjugated bilirubin, making ketogenic interventions relevant mainly for their effects on bilirubin handling and hepatic metabolism. A disease-modifying ketone-specific mechanism has not been established.', 'Nella sindrome di Gilbert, digiuno e restrizione energetica possono aumentare la bilirubina non coniugata, rendendo gli interventi chetogenici rilevanti soprattutto per i loro effetti sulla gestione della bilirubina e sul metabolismo epatico. Non è stato dimostrato un meccanismo specifico dei chetoni capace di modificare la malattia.'), 'covid-19-metabolism': ('Ketogenic approaches were investigated in COVID-19 through links between glucose metabolism, immunometabolism, inflammatory signaling and β-hydroxybutyrate. These mechanisms remain context-dependent and ketogenic therapy is not an established treatment for acute SARS-CoV-2 infection.', 'Gli approcci chetogenici sono stati studiati nel COVID-19 attraverso i legami tra metabolismo del glucosio, immunometabolismo, segnalazione infiammatoria e β-idrossibutirrato. Questi meccanismi restano dipendenti dal contesto e la terapia chetogenica non è un trattamento consolidato dell’infezione acuta da SARS-CoV-2.'), 'aesthetic-medicine-body-composition': ('In body-composition applications, ketogenic and very-low-energy ketogenic diets act primarily through energy restriction, appetite modulation and changes in substrate use that favor fat loss. Preservation of lean mass depends on protein adequacy, resistance exercise and the rate of weight loss.', 'Nelle applicazioni relative alla composizione corporea, le diete chetogeniche e chetogeniche a bassissimo apporto energetico agiscono soprattutto attraverso restrizione energetica, modulazione dell’appetito e modificazioni nell’utilizzo dei substrati che favoriscono la perdita di grasso. La preservazione della massa magra dipende da adeguato apporto proteico, esercizio di resistenza e velocità del dimagrimento.')}

STANDARD_RE = re.compile(
    r'<div class="folder-body">\s*<p(?:\s+[^>]*)?>.*?</p>',
    flags=re.S,
)

def make_block(en: str, it: str) -> str:
    return (
        '<div class="folder-body">\n'
        '<p class="folder-rationale">'
        '<strong data-en="Biological rationale:" '
        'data-it="Razionale biologico:">Biological rationale:</strong> '
        f'<span data-en="{html.escape(en, quote=True)}" '
        f'data-it="{html.escape(it, quote=True)}">{html.escape(en)}</span>'
        '</p>'
    )

def patch_folder(text: str, folder_id: str, en: str, it: str):
    start_match = re.search(
        rf'<details\b[^>]*\bid="{re.escape(folder_id)}"[^>]*>',
        text,
        flags=re.I,
    )
    if not start_match:
        return text, False, f"missing folder: {folder_id}"

    next_match = re.search(
        r'<details\b[^>]*class="[^"]*\blibrary-folder\b[^"]*"',
        text[start_match.end():],
        flags=re.I,
    )
    end = (
        start_match.end() + next_match.start()
        if next_match else len(text)
    )
    section = text[start_match.start():end]

    body_match = re.search(
        r'<div class="folder-body">\s*<p(?:\s+[^>]*)?>.*?</p>',
        section,
        flags=re.S,
    )
    if not body_match:
        return text, False, f"missing intro paragraph: {folder_id}"

    replacement = make_block(en, it)
    section = (
        section[:body_match.start()]
        + replacement
        + section[body_match.end():]
    )
    return (
        text[:start_match.start()]
        + section
        + text[end:],
        True,
        "",
    )

def main():
    text = LIBRARY.read_text(encoding="utf-8")
    changed = 0
    warnings = []

    for folder_id, (en, it) in RATIONALES.items():
        text, did_change, warning = patch_folder(
            text, folder_id, en, it
        )
        if did_change:
            changed += 1
        elif warning:
            warnings.append(warning)

    LIBRARY.write_text(text, encoding="utf-8")
    print(f"Clinical rationales applied: {changed}/{len(RATIONALES)}")
    for warning in warnings:
        print("WARNING:", warning)

    if changed != len(RATIONALES):
        raise SystemExit(
            f"Expected {len(RATIONALES)} folders, patched {changed}."
        )

if __name__ == "__main__":
    main()
